<section class="admin-page-head"><div><p class="admin-kicker">SUCURSALES</p><h1><?= $branch === null ? 'Nueva sucursal' : 'Editar sucursal' ?></h1><p>La clave es estable y no puede modificarse después del alta.</p></div><a class="admin-secondary-button" href="/admin/branches">Volver</a></section>
<section class="admin-panel"><form method="post" action="<?= $branch === null ? '/admin/branches/create' : '/admin/branches/update' ?>" class="admin-form"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><?php if ($branch !== null): ?><input type="hidden" name="id" value="<?= e($branch->id) ?>"><?php endif ?>
<div class="admin-form-grid"><label class="admin-field"><span>Clave</span><input name="code" maxlength="50" required pattern="[A-Za-z0-9][A-Za-z0-9_\-]{0,49}" value="<?= e($branch?->code ?? '') ?>" <?= $branch !== null ? 'readonly' : '' ?>></label><label class="admin-field"><span>Nombre</span><input name="name" maxlength="150" required value="<?= e($branch?->name ?? '') ?>"></label></div>
<label class="admin-field"><span>Dirección</span><textarea name="address" maxlength="500" rows="3"><?= e($branch?->address ?? '') ?></textarea><small>Registra únicamente información oficial confirmada.</small></label>
<div class="admin-form-grid"><label class="admin-field"><span>Teléfono</span><input name="phone" maxlength="32" value="<?= e($branch?->phone ?? '') ?>"></label><label class="admin-field"><span>WhatsApp</span><input name="whatsapp" maxlength="32" value="<?= e($branch?->whatsapp ?? '') ?>"></label></div>
<label class="admin-field"><span>Correo</span><input type="email" name="email" maxlength="254" value="<?= e($branch?->email ?? '') ?>"></label>
<div class="admin-form-grid"><label class="admin-field"><span>Latitud</span><input name="latitude" inputmode="decimal" value="<?= e($branch?->latitude ?? '') ?>"></label><label class="admin-field"><span>Longitud</span><input name="longitude" inputmode="decimal" value="<?= e($branch?->longitude ?? '') ?>"></label></div>
<button class="admin-primary-button" type="submit"><?= $branch === null ? 'Crear sucursal inactiva' : 'Guardar cambios' ?></button></form></section>
